class ChatSticker {
  const ChatSticker(
    this.id,
    this.role,
    this.emotion, [
    this.pack = 'classic',
    this.keywords = const [],
  ]);
  final String id, role, emotion, pack;
  final List<String> keywords;
  String get asset => 'assets/stickers/$pack/$id.png';
  String get packId => 'stickers-$pack';
  String? get productId => pack == 'classic' ? null : 'sticker-$id';
  String get label => '$role · $emotion';
}

